23: void mandelbrot_serial(float x0, float y0, float x1, float y1, int width, int height, int maxIterations, int output[], int threads) {
24:     float dx = (x1 - x0) / width;
25:     float dy = (y1 - y0) / height;
26: 
27:     #pragma omp parallel for schedule(guided, 4) num_threads(threads)
28:     for (int j = 0; j < height; j++) {
29:         for (int i = 0; i < width; ++i) {
30:             float x = x0 + i * dx;
31:             float y = y0 + j * dy;
32: 
33:             int index = (j * width + i);
34:             output[index] = mandel(x, y, maxIterations);
35:         }
36:     }
37: }
